import { OverlaysEventEmitter } from '@game-studio/overlays';
import { IBeginRequest, IContinueRequest, IResumeRequest, RESULT_CODES, ResultCodeData, SiteId } from '@game-studio/server-comms';

import { container, Injects, loggingModel } from '..';
import { gameConfig } from '../models/config-model';
import { inversifyContainer } from '../inversify/container';
import { demoState } from '../models/demo-model';
import { sessionDataModel } from '../models/session-data';
import { userModel } from '../models/user';
import { endGameValidator } from '../services/end-game-verification';
import { environment } from '../services/environment';
import { eventEmitter } from '../services/event-emitter';
import { queryStringParams } from '../services/query-string';
import { isInternationalBuild } from '../services/utilities';
import { IBaseMessageResponse, IBaseServerResponse, IBaseSettingsResponse } from '../types';
import { AbstractGameServer } from './abstract-server';
import { ContinueQueue, IContinueQueueItem } from './continue-queue';

interface IBaseReqeustData {
    ApiVersion?: string;
}
export class BaseGameServer extends AbstractGameServer {
    private siteId: SiteId | undefined = 'Arcade';
    private baseRequestData: IBaseReqeustData = {};
    private debugEngineVersion: string = '';

    constructor() {
        super();

        if (queryStringParams.launchedFrom === 'bingo') {
            this.siteId = 'Bingo';
        }

        if (isInternationalBuild() && !queryStringParams.isUnAuthDemoMode) {
            // international engines do not support the siteId and will error
            this.siteId = undefined;

            const apiVersion: string = inversifyContainer.isBound(Injects.InternationalEngineApiVersion) ? inversifyContainer.get(Injects.InternationalEngineApiVersion) : '2.0';
            this.baseRequestData = { ApiVersion: apiVersion };
        }
        this.setUpEventListeners();
    }

    public setUpEventListeners(): void {
        // inversifyContainer.frameConnection.publishToast.bind(inversifyContainer.frameConnection);

        this.on('ON_BONUSINPLAY_ERROR', () => {
            // if (queryStringParams.launchedFrom === 'bingo') {
            //     inversifyContainer.frameConnection.publishToast(inversifyContainer.strings.errorBonusInPlay);
            // } else {
            //     inversifyContainer.frameConnection.onExitGame();
            //     inversifyContainer.frameConnection.onEnterLobby(gameConfig.gameCategory);
            // }
            OverlaysEventEmitter.emit('showToast', '', inversifyContainer.strings.errorBonusInPlay);
        });

        this.on('ON_NETWORK_ERROR', () => {
            OverlaysEventEmitter.emit('showToast', '', inversifyContainer.errorStrings.networkOffline);
        });

        this.on('ON_ERROR_TO_NOTIFY', (result: ResultCodeData) => {
            OverlaysEventEmitter.emit('showToast', '', inversifyContainer.errorStrings[result.ResultCode]);
        });

        this.on('ON_NOTAUTHORISED_ERROR', () => {
            inversifyContainer.frameConnection.operator.onUserActionRequired({ type: 'id-verification' });
        });

        this.on('ON_NOSESSION_ERROR', (response: IBaseServerResponse) => {
            if (!demoState.isDemoMode) {
                eventEmitter.emit('POPUP_SHOW_WALLET', response);
            }
        });

        this.on('ON_GAME_UNAVAILABLE', (responseData: IBaseServerResponse) => {
            OverlaysEventEmitter.emit('showToast', '', inversifyContainer.errorStrings[responseData.ResultCode.ResultCode]);
            // window.setTimeout(() => {
            //     inversifyContainer.frameConnection.goToHome();
            // }, 5000);
        });

        this.on('ON_INVALID_STAKE', () => {
            const arcadeLowestStake = 10;
            const bingoLowestStake = 5;
            let minimumStakeRequired = this.siteId === 'Bingo' ? bingoLowestStake : arcadeLowestStake;

            /* Uses the default stake as the minimum so it can be dictated by engine.
                Engine currently sets this to 0 when there is no stakeOptions, we only want to use this once engine
                has done their change and doesn't return 0. */
            if (container.gameSettings.defaultStake && container.gameSettings.defaultStake !== 0) {
                minimumStakeRequired = container.gameSettings.defaultStake;
            }

            if (container.gameSettings.minimumStake) {
                minimumStakeRequired = container.gameSettings.minimumStake;
            }

            const formattedString = container.currencyFormatter.precise(minimumStakeRequired);
            let displayName = '';

            if (typeof container.strings.displayName === 'string') {
                displayName = container.strings.displayName;
            } else {
                displayName = container.strings.displayName[queryStringParams.currentSkin];
            }

            if (userModel.freePlayBalance > 0) { return; }

            inversifyContainer.frameConnection.operator.onUserActionRequired({
                type: 'invalid-stake-limit',
                data: {
                    gameName: displayName,
                    minRequiredStakeAsPence: minimumStakeRequired,
                    minRequiredStake: formattedString,
                }
            });

            this.preventPurchaseAttempts = true;
        });

        eventEmitter.on('DEBUG_ENGINE_VERSION_SET', (debugEngineVersion: string) => {
            this.debugEngineVersion = debugEngineVersion;
        });
    }

    public async resumeRequest<TResponse extends IBaseServerResponse = IBaseServerResponse>(skinName: string): Promise<TResponse> {
        /**
         * Three Possible Modes for Resume:
         * 1. Unauthenticated Demo: User not logged in, playing demo with operatorId only
         * 2. Authenticated Demo: User logged in, toggled demo mode via settings menu
         * 3. Normal: User logged in, playing with real money
         */

        let resumeRequestData: IResumeRequest;

        if (demoState.isUnauthenticatedDemo) {
            resumeRequestData = {
                OperatorId: 'IT_DEMO',
                CrossCheck: 100,
                ...this.baseRequestData
            };
        } else {
            resumeRequestData = {
                CrossCheck: userModel.crossCheck,
                UserId: userModel.userId,
                ClientTypeId: userModel.clientTypeId,
                SiteId: this.siteId,
                ...this.baseRequestData
            };

            // Add skin parameter for authenticated requests
            if (gameConfig.features.engineRequiresSkinParam) {
                resumeRequestData.Skin = skinName;

                // If we need a skin but the engine name is `unknown`, force the skin to be `bubble`;
                if (gameConfig.engineName === 'unknown') { resumeRequestData.Skin = 'bubble'; }
            }
        }

        if (gameConfig.features.engineRequiresSkinParam) {
            resumeRequestData.Skin = skinName;

            // If we need a skin but the engine name is `unknown`, force the skin to be `bubble`;
            if (gameConfig.engineName === 'unknown') { resumeRequestData.Skin = 'bubble'; }
        }

        // If user toggled demo mode while authenticated, add PlayMode: 'Demo'
        if (demoState.isDemoMode) {
            Object.assign(resumeRequestData, { PlayMode: 'Demo' });
        }

        const response = await this.resume<IResumeRequest, TResponse>(resumeRequestData);

        if (gameConfig.engineName === 'unknown') {
            if (response.GameMessage && inversifyContainer.gameModel.dummyMessage) {
                response.GameMessage = inversifyContainer.gameModel.dummyMessage;
            }
            if (response.GameSettings) {
                const engineVersion = response.GameSettings.Version;

                response.GameSettings = inversifyContainer.gameSettings.dummySettings || {} as IBaseSettingsResponse;
                response.GameSettings.Version = engineVersion;
            }
        }

        return response;
    }

    public async beginRequest<TResponse extends IBaseServerResponse = IBaseServerResponse>(skinName: string, freePlay: boolean): Promise<TResponse> {
        if (this.preventPurchaseAttempts) {
            throw new Error('Attempted to purchase with preventPurchaseAttempts true');
        }

        let beginRequestData: IBeginRequest;

        if (demoState.isUnauthenticatedDemo) {
            beginRequestData = {
                OperatorId: 'IT_DEMO',
                PlayMode: 'Demo',
                UserId: userModel.userId,
                CrossCheck: userModel.crossCheck,
                Stake: inversifyContainer.stake.currentStake,
                ...this.baseRequestData
            } as IBeginRequest;
        } else {
            beginRequestData = {
                Version: inversifyContainer.gameSettings.engineVersion,
                CrossCheck: userModel.crossCheck,
                UserId: userModel.userId,
                ClientTypeId: userModel.clientTypeId,
                SiteId: this.siteId,
                BingoParentGame: queryStringParams.parentGame,
                ...this.baseRequestData
            };

            if (inversifyContainer.adminSettings)
                if (freePlay) {
                    Object.assign(beginRequestData, { PlayMode: 'FreePlay' });
                } else if (demoState.isAuthenticatedDemo) {
                    Object.assign(beginRequestData, { PlayMode: 'Demo' });
                    Object.assign(beginRequestData, { Stake: inversifyContainer.stake.currentStake });
                } else {
                    Object.assign(beginRequestData, { Stake: inversifyContainer.stake.currentStake });
                }
        }

        // Apply skin logic for both authenticated and unauthenticated modes
        if (gameConfig.features.engineRequiresSkinParam) {
            beginRequestData.Skin = skinName;

            // If we need a skin but the engine name is `unknown`, force the skin to be `bubble`;
            if (gameConfig.engineName === 'unknown') { beginRequestData.Skin = 'bubble'; }
        }

        if (environment !== 'live') {
            if (inversifyContainer.debugModel.shouldSendDebugData) {
                Object.assign(beginRequestData, inversifyContainer.debugModel.debugServerData);
            }

            if ((environment === 'debug' || environment === 'dev') && !isInternationalBuild()) {
                Object.assign(beginRequestData, { DebugNotification: true });
            }

            if (this.debugEngineVersion !== '') {
                Object.assign(beginRequestData, { DebugVersion: this.debugEngineVersion });
            }
        }

        if (inversifyContainer.gameModel.additionalBeginData) {
            Object.assign(beginRequestData, inversifyContainer.gameModel.additionalBeginData);
        }

        if (queryStringParams.locale === 'es-es') {
            Object.assign(beginRequestData, { SessionId: sessionDataModel.status.SessionId });
        }

        loggingModel.logPurchaseEvent('purchaseAttempt', 'Purchase attempt made');

        return this.begin<IBeginRequest, TResponse>(beginRequestData).then((response) => {
            endGameValidator.startGame(response);

            if (gameConfig.engineName === 'unknown') {
                if (response.GameMessage) {
                    response.GameMessage = inversifyContainer.gameModel.dummyMessage || {} as IBaseMessageResponse;
                }
                if (response.GameSettings) {
                    response.GameSettings = inversifyContainer.gameSettings.dummySettings || {} as IBaseSettingsResponse;
                }
            }

            if (response.DemoSettings) {
                demoState.demoGamesRemaining = response.DemoSettings.RemainingDemoGames;
            }

            if (response.SessionStatus?.FunBonusConversionFailed && inversifyContainer.strings.errorFunBonusConversionFailed) {
                OverlaysEventEmitter.emit('showToast', '', inversifyContainer.strings.errorFunBonusConversionFailed);
            }

            loggingModel.logPurchaseEvent('purchaseSuccess', 'Purchase completed');
            return response;
        }).catch((err) => {
            if (demoState.isDemoMode && demoState.demoGamesRemaining <= 0) {
                demoState.leaveDemoMode();
            }

            const errorMesssage = inversifyContainer.errorStrings[err.ResultCode.ResultCode] || 'Unknown purchase error occurred';
            loggingModel.logPurchaseEvent('purchaseFailed', errorMesssage);

            // Handle receiving freeplays while you have an arcade game open. Prevents a refresh being required to use freeplays.
            if (err.ResultCode.ResultCode === RESULT_CODES.INTERNATIONAL_SESSION_ALREADY_ENDED && err.PlayerData.FreePlayBalance > 0) {
                userModel.setData(err.PlayerData, err.RequestType);
            }

            throw err;
        });
    }

    public async continueRequest<TResponse extends IBaseServerResponse = IBaseServerResponse>(additionalData: object): Promise<TResponse> {
        let continueRequestData: IContinueRequest;

        if (demoState.isUnauthenticatedDemo) {
            continueRequestData = {
                OperatorId: 'IT_DEMO',
                ClientTypeId: userModel.clientTypeId,
                CrossCheck: userModel.crossCheck,
                UserId: userModel.userId,
                Stake: inversifyContainer.stake.currentStake,
                ...this.baseRequestData,
                ...additionalData
            };

            Object.assign(continueRequestData, { PlayMode: 'Demo' });
        } else {
            continueRequestData = {
                ClientTypeId: userModel.clientTypeId,
                CrossCheck: userModel.crossCheck,
                UserId: userModel.userId,
                Stake: inversifyContainer.stake.currentStake,
                SiteId: this.siteId,
                ...this.baseRequestData,
                ...additionalData
            };

            if (demoState.isDemoMode) {
                Object.assign(continueRequestData, { PlayMode: 'Demo' });
            } else {
                Object.assign(continueRequestData, { PlayMode: inversifyContainer.gameModel.playMode });
            }
        }

        if (gameConfig.features.engineRequiresSkinParam) {
            continueRequestData.Skin = gameConfig.engineSkinName;
        }

        return this.continue<IContinueRequest, TResponse>(continueRequestData).then((response) => {
            if (response.DemoSettings) {
                demoState.demoGamesRemaining = response.DemoSettings.RemainingDemoGames;
            }

            userModel.setData(response.PlayerData, response.RequestType, response.GameMessage.GameComplete);
            sessionDataModel.setData(response);

            if (response.SessionStatus?.FunBonusConversionFailed && inversifyContainer.strings.errorFunBonusConversionFailed) {
                OverlaysEventEmitter.emit('showToast', '', inversifyContainer.strings.errorFunBonusConversionFailed);
            }

            endGameValidator.continueGame(response);
            return response;
        });
    }

    public queueContinueRequest(item: IContinueQueueItem): void {
        ContinueQueue.enqueue(item);
    }
}
